// Process all schemes
$count = 0;
foreach ($schemes as $id => $data) {
    $s = App\Models\Scheme::find($id);
    if (!$s) { echo "NOT FOUND: ID=$id\n"; continue; }
    
    // Only update fields that have content defined
    foreach (['content','eligibility','benefits','application_process','required_documents'] as $f) {
        if (isset($data[$f])) {
            $s->$f = $data[$f];
        }
    }
    $s->save();
    
    // Count words
    $text = strip_tags(implode(' ', [$s->content, $s->eligibility, $s->benefits, $s->application_process, $s->required_documents]));
    $words = preg_match_all("/\p{L}+/u", $text, $m);
    echo "OK ID=$id: {$s->title} - $words total words\n";
    $count++;
}

echo "\n--- TOTAL: $count schemes expanded ---\n";

// Final stats
$all = App\Models\Scheme::all();
$over400 = 0; $totalWords = 0;
foreach ($all as $s) {
    $text = strip_tags(implode(' ', [$s->content, $s->eligibility, $s->benefits, $s->application_process, $s->required_documents]));
    $words = preg_match_all("/\p{L}+/u", $text, $m);
    $totalWords += $words;
    if ($words >= 400) $over400++;
}
echo "Schemes with >=400 words: $over400 / {$all->count()}\n";
echo "Average word count: " . round($totalWords / $all->count()) . "\n";

// Auto-export to MySQL
echo "\n--- Exporting to MySQL update SQL ---\n";
$fields = ['content','eligibility','benefits','application_process','required_documents'];
$sql = "-- MySQL content updates\n-- Generated: " . date('Y-m-d H:i:s') . "\n\n";
foreach ($all as $s) {
    $sets = [];
    foreach ($fields as $f) {
        $v = $s->$f;
        if ($v !== null && $v !== '') {
            $escaped = str_replace("'", "\\'", $v);
            $sets[] = "`$f`='$escaped'";
        }
    }
    if (count($sets) > 0) {
        $sql .= "UPDATE schemes SET " . implode(', ', $sets) . " WHERE `slug`='{$s->slug}';\n";
    }
}
file_put_contents(__DIR__ . '/update_mysql.sql', $sql);
echo "Written update_mysql.sql: " . filesize(__DIR__ . '/update_mysql.sql') . " bytes\n";